globalThis.createStore = function () {
  const items = [];
  let nextId = 1;

  return {
    add(title) {
      if (typeof title !== 'string') throw new Error('title must be a string');
      const trimmed = title.trim();
      if (trimmed === '') {
        throw new Error('title cannot be empty after trimming');
      }
      const id = nextId++;
      items.push({ id, title: trimmed, done: false });
      return id;
    },
    remove(id) {
      const index = items.findIndex((item) => item.id === id);
      if (index !== -1) {
        items.splice(index, 1);
      }
    },
    toggle(id) {
      const item = items.find((item) => item.id === id);
      if (!item) return false;
      item.done = !item.done;
      return item.done;
    },
    list(filter = 'all') {
      let filtered = items;
      if (filter === 'done') {
        filtered = items.filter((item) => item.done);
      } else if (filter === 'active') {
        filtered = items.filter((item) => !item.done);
      }
      return filtered.map((item) => ({ id: item.id, title: item.title, done: item.done }));
    },
  };
};

